import numpy as np
import json

with open("/home/ubuntu/runs/paper/qwen-h-in-glm-hpl-u1-light/frozen/stream-000/play/users/u042/system/state/workspace/programs/task-0f6e5a2f.json", "r") as f:
    demos = json.load(f)

def get_fg_colors(demo):
    """Get colors that are NOT background (not 0) in input"""
    inp = np.asarray(demo['input'])
    # Count colors
    color_counts = {}
    for r in range(inp.shape[0]):
        for c in range(inp.shape[1]):
            v = inp[r, c]
            if v != 0:
                color_counts[v] = color_counts.get(v, 0) + 1
    return color_counts

def get_bg_color_of_output(demo):
    """Get background color of output (most common color)"""
    out = np.asarray(demo['output'])
    return np.bincount(out.flatten()).argmax()

# For each demo, what is the output background?
for demo_num in range(len(demos)):
    d = demos[demo_num]
    out = np.asarray(d['output'])
    bg = np.bincount(out.flatten()).argmax()
    fg = get_fg_colors(d)
    fg_filtered = {c: n for c, n in fg.items() if c != bg}
    print(f"Demo {demo_num}: output bg={bg}, colors in input (excluding bg): {sorted(fg_filtered.keys())}")

    # What does color 0 mean?
    out0_count = np.bincount(out.flatten()).early_catch[0]
    print(f"  output[0] count: {out0_count}")

