import json
import numpy as np
from collections import deque, defaultdict

# Re-read test input
with open("/home/ubuntu/runs/paper/qwen-h-in-glm-hpl-u1-light/frozen/stream-000/play/users/u042/system/state/workspace/programs/task-0f6e5a2f.json", 'r') as f:
    json_data = json.load(f)

test_input = np.array(json_data[1]['input'])
bg_color = np.bincount(test_input.flatten()).argmax()  # Should be 9

def get_connected_components_4(grid, bg_color):
    h, w = grid.shape
    components = {}
    visited = np.zeros_like(grid, dtype=bool)
    comp_id = 0

    for r in range(h):
        for c in range(w):
            if grid[r, c] != bg_color and not visited[r, c]:
                color = grid[r, c]
                cells = []
                queue = deque([(r, c)])
                visited[r, c] = True

                while queue:
                    cr, cc = queue.popleft()
                    cells.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr, nc] == color and not visited[nr, nc]:
                                visited[nr, nc] = True
                                queue.append((nr, nc))

                components[color] = cells
    return components

def get_min_distance_to_frame(component_cells, frame_cells):
    min_dist = float('inf')
    for cr, cc in component_cells:
        for fr, fc in frame_cells:
            dist = abs(cr - fr) + abs(cc - fc)
            min_dist = min(min_dist, dist)
    return min_dist

def find_arrow_harm(component_cells):
    rows = set(cr for cr, cc in component_cells)
    col_counts = {}
    for cr, cc in component_cells:
        col_counts[cr] = col_counts.get(cr, 0) + 1
    max_count = max(col_counts.values())

    for row, count in col_counts.items():
        if count >= 3 and count == max_count:
            return [(r, c) for r, c in component_cells if r == row]
    return []

def get_normalized_shape(component_cells):
    """Returns a tuple representing the normalized crop tuple"""
